    return {"provider":"rule-based-fallback","topic":topic,"level":level,"label":"Generated study aid","disclaimer":"For learning only. Verify clinical facts with current authoritative guidance; not medical advice.","sections":[{"heading":"Overview","content":f"Start by defining {topic} and explaining why it matters in healthcare education."},{"heading":"Key concepts","content":"Identify the main terms, underlying principles, common applications, and limitations. Compare ideas using a simple table or concept map."},{"heading":"How to study this topic","content":"Use an official guideline or textbook, take structured notes, and test recall without looking at the source."},{"heading":"Revision points","items":[f"Define {topic} in your own words.","Explain two core concepts.","Identify one limitation or safety consideration.","Name an authoritative source to consult."]}],"selfTest":[{"question":f"How would you explain {topic} to a new learner?","answer":"Give a concise definition, purpose, and one supported example."},{"question":"Why should healthcare study notes be checked against authoritative sources?","answer":"Guidance changes and simplified notes may omit context or important safety details."}]}
